/**
 * Supabase/PostgREST client for the backup mirror.
 *
 * ## Why PostgREST and not `pg`
 *
 * A Worker cannot open a raw TCP socket, so there is no Postgres wire protocol
 * available to it. PostgREST's HTTPS surface over the mirror schema is the
 * supported way in, and it happens to fit this workload: the syncer only ever
 * needs "upsert this array of rows", which is one autogenerated endpoint.
 *
 * ## Failure semantics
 *
 * Every push is retried, and every retry is safe: the write is an upsert keyed on
 * the mirror's primary key, so a request that succeeded but whose response was
 * lost costs a repeated write and never a duplicated row. That is the whole reason
 * the pipeline can be at-least-once (see `packages/shared/src/backup.ts`).
 *
 * Retries are bounded and the error is *returned*, not thrown away, because the
 * two failures worth distinguishing look identical from the outside:
 *
 *   * `401`/`403` — the service-role key is wrong. Retrying will not help; the
 *     operator has to act, and the status endpoint must say so.
 *   * `404` with `PGRST205` — the schema is not exposed to PostgREST yet. Also an
 *     operator action (see `scripts/supabase-backup.mjs expose`).
 *   * `409`/`400` — the mirror's DDL and this plan disagree. A bug here, not a
 *     transient fault, so it must not be swallowed as "will retry".
 *   * `429`/`5xx` — genuinely transient; back off and try again.
 *
 * The error text carries the PostgREST `code`/`message`/`details` triple verbatim
 * so a failure lands in `/v1/backup/status` saying what to fix.
 */

import type { BackupRow } from "@custom-wayback/shared";

export interface SupabaseConfig {
  url: string;
  serviceRoleKey: string;
  /** Mirrored schema. Defaults to `cw_backup`; see supabase/migrations. */
  schema: string;
}

/** The subset of `Env` this client needs, so tests can pass a literal. */
export interface SupabaseEnv {
  SUPABASE_URL?: string;
  SUPABASE_SERVICE_ROLE_KEY?: string;
  SUPABASE_SCHEMA?: string;
}

export const DEFAULT_SUPABASE_SCHEMA = "cw_backup";

/**
 * Read the Supabase settings out of the environment.
 *
 * Returns `null` rather than throwing when unset — the backup is optional, and a
 * deployment that has never configured it must still boot, serve traffic and
 * report `configured: false`. Throwing here would turn "backup not set up yet"
 * into "Worker is broken".
 *
 * The URL is normalised without its trailing slash so path joins stay predictable,
 * and both halves are required: a URL with no key fails at the first push with a
 * 401, which is a worse error message than demanding both up front.
 */
export function supabaseConfigFromEnv(env: SupabaseEnv): SupabaseConfig | null {
  const rawUrl = env.SUPABASE_URL?.trim();
  const serviceRoleKey = env.SUPABASE_SERVICE_ROLE_KEY?.trim();
  if (!rawUrl || !serviceRoleKey) return null;

  let url: string;
  try {
    url = new URL(rawUrl).origin;
  } catch {
    return null;
  }

  const schema = env.SUPABASE_SCHEMA?.trim() || DEFAULT_SUPABASE_SCHEMA;
  return { url, serviceRoleKey, schema };
}

export interface PushResult {
  ok: boolean;
  status: number;
  /** Rows the request carried. Counted even on failure, as "attempted". */
  rows: number;
  /** PostgREST error text, when there is one. Never includes the key. */
  error?: string;
  /** True when the failure is worth retrying later. */
  retryable: boolean;
  attempts: number;
}

export interface PushOptions {
  /** Injected so tests can drive the retry logic without a network. */
  fetchImpl?: typeof fetch;
  timeoutMs?: number;
  maxAttempts?: number;
  /** Base delay for the exponential backoff, in ms. */
  backoffBaseMs?: number;
  /** Injected sleep, so a test does not spend real seconds on backoff. */
  sleep?: (ms: number) => Promise<void>;
}

const defaultSleep = (ms: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Build a `RequestInit` without any property set to `undefined`.
 *
 * The repo compiles with `exactOptionalPropertyTypes`, under which
 * `{ signal: undefined }` is *not* the same as omitting `signal` — and Workers'
 * `RequestInit` types the field as `AbortSignal | null`, so spreading a possibly
 * undefined timeout in produces a type error that a `!` would only hide. The
 * timeout is genuinely optional here (the CLI has no Worker CPU ceiling to respect
 * and the tests want no timer at all), so it is omitted rather than faked.
 *
 * Exported because the syncer issues its own requests to `backup_state` and must
 * satisfy the same constraint; one helper means one place to get it right.
 */
export function initWith(
  method: string,
  headers: Record<string, string>,
  timeoutMs: number | undefined,
  body?: string,
): RequestInit {
  const init: RequestInit = { method, headers };
  if (body !== undefined) init.body = body;
  if (timeoutMs !== undefined) init.signal = AbortSignal.timeout(timeoutMs);
  return init;
}

/**
 * Upsert `rows` into one mirror table.
 *
 * The body is a JSON array. PostgREST maps it onto the table's columns by name,
 * casts JSON booleans to `boolean` and base64 strings to `bytea` — the two
 * conversions `toPostgrestRow` exists to produce.
 *
 * `on_conflict` names the primary key explicitly. PostgREST will otherwise guess,
 * and a guess that picks a different unique index raises
 * `42P10: there is no unique or exclusion constraint matching the ON CONFLICT
 * specification` — an error that reads like a DDL problem but is really a request
 * problem, so it is pinned here instead.
 */
export async function pushRows(
  config: SupabaseConfig,
  table: string,
  rows: readonly BackupRow[],
  conflictColumns: string | null,
  options: PushOptions = {},
): Promise<PushResult> {
  if (rows.length === 0) {
    return { ok: true, status: 204, rows: 0, retryable: false, attempts: 0 };
  }

  const fetchImpl = options.fetchImpl ?? fetch;
  const maxAttempts = options.maxAttempts ?? 3;
  const backoffBaseMs = options.backoffBaseMs ?? 500;
  const sleep = options.sleep ?? defaultSleep;

  const url = new URL(`${config.url}/rest/v1/${encodeURIComponent(table)}`);
  if (conflictColumns) url.searchParams.set("on_conflict", conflictColumns);

  const headers: Record<string, string> = {
    apikey: config.serviceRoleKey,
    Authorization: `Bearer ${config.serviceRoleKey}`,
    "Content-Type": "application/json",
    // `merge-duplicates` is the upsert; without it a repeat row is a 409.
    Prefer: "resolution=merge-duplicates,return=minimal",
    // Tell PostgREST which schema to resolve the table in. `Accept-Profile`
    // applies to reads, `Content-Profile` to writes; sending the write header is
    // what makes the insert land in cw_backup rather than public.
    "Content-Profile": config.schema,
  };

  const body = JSON.stringify(rows);
  let lastError = "no attempt made";
  let lastStatus = 0;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    let response: Response;
    try {
      response = await fetchImpl(
        url.toString(),
        initWith("POST", headers, options.timeoutMs, body),
      );
    } catch (err) {
      // A network fault or a timeout: transient by definition here.
      lastError = err instanceof Error ? err.message : String(err);
      lastStatus = 0;
      if (attempt < maxAttempts) {
        await sleep(backoffBaseMs * 2 ** (attempt - 1));
        continue;
      }
      break;
    }

    if (response.ok) {
      // Drain the body so the connection can be reused; `return=minimal` means
      // there is nothing to read.
      await response.body?.cancel().catch(() => void 0);
      return { ok: true, status: response.status, rows: rows.length, retryable: false, attempts: attempt };
    }

    lastStatus = response.status;
    lastError = await describeError(response);

    if (!isRetryableStatus(response.status)) {
      return {
        ok: false,
        status: response.status,
        rows: rows.length,
        error: lastError,
        retryable: false,
        attempts: attempt,
      };
    }

    if (attempt < maxAttempts) {
      const retryAfter = retryAfterMs(response);
      await sleep(retryAfter ?? backoffBaseMs * 2 ** (attempt - 1));
    }
  }

  return {
    ok: false,
    status: lastStatus,
    rows: rows.length,
    error: lastError,
    retryable: true,
    attempts: maxAttempts,
  };
}

/**
 * `429` and `5xx` are the transient set. A `409` is *not* retried even though it
 * looks like contention: with `resolution=merge-duplicates` a duplicate key
 * cannot occur, so a `409` here means the conflict target does not match the
 * mirror's constraints — a bug that would otherwise be retried three times and
 * then reported as a timeout.
 */
export function isRetryableStatus(status: number): boolean {
  return status === 408 || status === 425 || status === 429 || status >= 500;
}

function retryAfterMs(response: Response): number | null {
  const header = response.headers.get("retry-after");
  if (!header) return null;
  const seconds = Number(header);
  if (Number.isFinite(seconds)) return Math.min(seconds * 1000, 30_000);
  const at = Date.parse(header);
  return Number.isNaN(at) ? null : Math.max(0, Math.min(at - Date.now(), 30_000));
}

/**
 * Turn a PostgREST error response into one line worth storing.
 *
 * PostgREST answers with `{ message, details, hint, code }` — the `code` is the
 * useful part for an operator (`PGRST205` means the schema is not exposed,
 * `42P10` means the conflict target is wrong), so it leads. The body is truncated
 * defensively; it is remote text and lands in a database column.
 */
export async function describeError(response: Response): Promise<string> {
  let detail = "";
  try {
    detail = (await response.text()).slice(0, 500);
  } catch {
    detail = "";
  }

  let parsed: { code?: string; message?: string; details?: string; hint?: string } = {};
  try {
    parsed = JSON.parse(detail) as typeof parsed;
  } catch {
    // Not JSON (an HTML error page from a proxy, say). Use it raw.
  }

  const parts = [`HTTP ${response.status}`];
  if (parsed.code) parts.push(parsed.code);
  if (parsed.message) parts.push(parsed.message);
  if (parsed.details) parts.push(parsed.details);
  if (parsed.hint) parts.push(`hint: ${parsed.hint}`);
  return parts.length > 1 ? parts.join(" · ") : `${parts[0]} · ${detail || "no body"}`;
}

export interface PingResult {
  ok: boolean;
  /** Round-trip in ms, when the request completed. */
  latencyMs?: number;
  error?: string;
}

/**
 * One cheap authenticated request against the mirror, used by `/v1/health` and by
 * the CLI's `verify` command.
 *
 * Counts rows in `backup_state` rather than touching a ledger table: it proves the
 * key is accepted, the schema is exposed and the DDL is applied, without reading
 * anything large. `Prefer: count=exact` with `limit=0` is the cheapest form of
 * that — no rows come back at all.
 */
export async function pingMirror(
  config: SupabaseConfig,
  options: PushOptions = {},
): Promise<PingResult> {
  const fetchImpl = options.fetchImpl ?? fetch;
  const url = new URL(`${config.url}/rest/v1/backup_state`);
  url.searchParams.set("select", "table_name");
  url.searchParams.set("limit", "0");

  const started = Date.now();
  try {
    const response = await fetchImpl(
      url.toString(),
      initWith(
        "HEAD",
        {
          apikey: config.serviceRoleKey,
          Authorization: `Bearer ${config.serviceRoleKey}`,
          "Accept-Profile": config.schema,
        },
        options.timeoutMs,
      ),
    );
    if (!response.ok) {
      return { ok: false, error: await describeError(response), latencyMs: Date.now() - started };
    }
    await response.body?.cancel().catch(() => void 0);
    return { ok: true, latencyMs: Date.now() - started };
  } catch (err) {
    return {
      ok: false,
      error: err instanceof Error ? err.message : String(err),
      latencyMs: Date.now() - started,
    };
  }
}
